	@Requirement
	public static SysMLRequirement rid2_5_3_1_2_3 = new SysMLRequirement(
		"2.5.3.1.2.3", "Component DeployedModemRadio \"OperationalOnEthernetIPPacket\" Transition",
		"Component DeployedModemRadio shall perform the specified Action as part of internal transition OperationalOnEthernetIPPacket in state Operational as follows\nTransition OperationalOnEthernetIPPacket shall occur upon the occurance of triggering event noname and if the following condition is satisfied.\n{\n(event, contextBlock) -> {\n    return event.isPresent() && event.get() instanceof SysMLSignalEvent signalEvent && signalEvent.signal instanceof IPPacketSignal;\n}\n}\nTransition OperationalOnEthernetIPPacket shall result in performance of the following Action upon occurance.\n{\n(event, contextBlock) -> {\n    IPPacket ipPacket = ((IPPacketSignal) ((SysMLSignalEvent) event.get()).signal).packet;\n    ModemRadio modemRadio = (ModemRadio) contextBlock.get();\n    modemRadio.processIPPacketFromEthernet(ipPacket);\n}\n}",
		Optional.empty(), Optional.empty(), List.of(), List.of(), List.of(),
		false, List.of(), RequirementCategoryEnum.StatesTransitions,
		List.of(), List.of(Demonstration), List.of(), List.of());
	@Requirement
	public static SysMLRequirement rid2_5_3_1_2_4 = new SysMLRequirement(
		"2.5.3.1.2.4", "Component DeployedModemRadio \"OperationalOnDataLinkFrame\" Transition",
		"Component DeployedModemRadio shall perform the specified Action as part of internal transition OperationalOnDataLinkFrame in state Operational as follows\nTransition OperationalOnDataLinkFrame shall occur upon the occurance of triggering event noname and if the following condition is satisfied.\n{\n(event, contextBlock) -> {\n    return event.isPresent() && event.get() instanceof SysMLSignalEvent signalEvent && signalEvent.signal instanceof DataLinkFrameSignal;\n}\n}\nTransition OperationalOnDataLinkFrame shall result in performance of the following Action upon occurance.\n{\n(event, contextBlock) -> {\n    DataLinkFrame datalinkFrame = ((DataLinkFrameSignal) ((SysMLSignalEvent) event.get()).signal).frame;\n    ModemRadio modemRadio = (ModemRadio) contextBlock.get();\n    modemRadio.processIPPacketFromDataLink(datalinkFrame);\n}\n}",
		Optional.empty(), Optional.empty(), List.of(), List.of(), List.of(),
		false, List.of(), RequirementCategoryEnum.StatesTransitions,
		List.of(), List.of(Demonstration), List.of(), List.of());
	@Requirement
	public static SysMLRequirement rid2_5_3_1_2_5 = new SysMLRequirement(
		"2.5.3.1.2.5", "Component DeployedModemRadio \"OperationalOnGPSMessage\" Transition",
		"Component DeployedModemRadio shall perform the specified Action as part of internal transition OperationalOnGPSMessage in state Operational as follows\nTransition OperationalOnGPSMessage shall occur upon the occurance of triggering event noname and if the following condition is satisfied.\n{\n(event, contextBlock) -> {\n    return event.isPresent() && event.get() instanceof SysMLSignalEvent signalEvent && signalEvent.signal instanceof GPSMessageSignal;\n}\n}\nTransition OperationalOnGPSMessage shall result in performance of the following Action upon occurance.\n{\n(event, contextBlock) -> {\n    GPSMessage gpsMessage = ((GPSMessageSignal) ((SysMLSignalEvent) event.get()).signal).message;\n    ModemRadio modemRadio = (ModemRadio) contextBlock.get();\n    modemRadio.processTDMASlotTimeFromGPS(gpsMessage);\n}\n}",
		Optional.empty(), Optional.empty(), List.of(), List.of(), List.of(),
		false, List.of(), RequirementCategoryEnum.StatesTransitions,
		List.of(), List.of(Demonstration), List.of(), List.of());
