	@Requirement
	public static SysMLRequirement rid4_5_2_1_2_3 = new SysMLRequirement(
		"4.5.2.1.2.3", "Component DeployedSwitchRouter \"OperationalOnIPPacket\" Transition",
		"Component DeployedSwitchRouter shall perform the specified Action as part of internal transition OperationalOnIPPacket in state Operational as follows\nTransition OperationalOnIPPacket shall occur upon the occurance of triggering event noname and if the following condition is satisfied.\n{\n(event, contextBlock) -> {\n    return event.isPresent() && event.get() instanceof SysMLSignalEvent signalEvent && signalEvent.signal instanceof IPPacketSignal;\n}\n}\nTransition OperationalOnIPPacket shall result in performance of the following Action upon occurance.\n{\n(event, contextBlock) -> {\n    if (event.get() instanceof SysMLSignalEvent signalEvent) {\n        IPPacket packet = ((IPPacketSignal) signalEvent.signal).packet;\n        EthernetSwitchIPRouter switchRouter = (EthernetSwitchIPRouter) contextBlock.get();\n        switchRouter.routeIPPacket(packet);\n    }\n}\n}",
		Optional.empty(), Optional.empty(), List.of(), List.of(), List.of(),
		false, List.of(), RequirementCategoryEnum.StatesTransitions,
		List.of(), List.of(Demonstration), List.of(), List.of());
